  'vault.doc.confirmedBlock': 'Bloque {block}',
  'vault.doc.privacyNote': 'Los archivos nunca se suben ni se almacenan — solo se sella el hash. Un sello confirmado prueba que este archivo exacto existía en ese bloque Bitcoin. Este registro se almacena solo en este dispositivo.',
