  'vault.tip.badgeVerified': 'Verificado en Bitcoin — Satohash confirma que esta ancla está en un bloque Bitcoin. El estado de prueba más fuerte.',
  'vault.tip.badgeRecorded': 'Prueba en archivo — el hash y el bloque están registrados aquí. Confirma en Satohash para el anclaje on-chain final.',
  'vault.tip.badgePending': 'Anclaje pendiente — enviado al servicio de sellado, esperando un bloque Bitcoin.',
  'vault.tip.badgeDemo': 'Ancla demo — un placeholder de datos semilla. Aún no sellada en Bitcoin.',
  'vault.tip.block': 'El bloque Bitcoin en el que está anclada esta prueba — una marca de tiempo permanente y pública que cualquiera puede verificar.',
  'vault.tip.checked': 'Cuándo se revisó por última vez este programa.',
  'vault.tip.hash': 'Huella SHA-256 de los datos anclados — prueba que este contenido exacto existía en ese bloque.',
  'vault.tip.ots': 'Recibo OpenTimestamps (.ots). Descárgalo para verificar de forma independiente — sin cuenta ni servicio.',
  'vault.tip.useProof': 'Adjunta este hash de prueba a una solicitud de pasaporte como evidencia.',
  'vault.tip.copyUrl': 'Copia el enlace de verificación Satohash para compartirlo o guardarlo.',
  'vault.tip.satohash': 'Abre Satohash.io para verificar esta prueba en Bitcoin.',
  'vault.tip.otsDownload': 'Descarga el recibo OpenTimestamps para verificación sin conexión.',
  'vault.tip.apply': 'Inicia una solicitud para este programa con su prueba pre-adjunta.',
  'vault.tip.nostr': 'Publica un anuncio de sello firmado en tus relays Nostr. Nostr es chisme — la prueba OTS/Satohash es la evidencia.',
  'vault.tip.lineage': 'Cada prueba registrada para este programa — mira cómo evolucionó la ancla con el tiempo.',
  'vault.tip.lineageEventId': 'Copia el ID de evento Nostr — tu anuncio de prueba firmado. Consérvalo para referenciar el evento más tarde.',
  'vault.how.eyebrow': 'CÓMO FUNCIONA',
  'vault.how.title': 'Por qué existe la Bóveda — y cómo usarla',
  'vault.how.intro': 'La Bóveda es el pilar Seal de MotoPass. Cada dato material del programa debería llevar un certificado de nacimiento Bitcoin. Esta página te permite auditar esas pruebas tú mismo — sin confianza de folleto.',
  'vault.how.step1.title': 'Qué se sella',
  'vault.how.step1.body': 'Las capturas de programas insignia — costos, extractos legales, notas de vía — se hasean y anclan a Bitcoin vía OpenTimestamps. Satohash.io proporciona recibos de verificación legibles con altura de bloque.',
  'vault.how.step2.title': 'Anclas verificadas vs demo',
  'vault.how.step2.body': 'Las pruebas verificadas tienen URLs Satohash reales y archivos .ots opcionales en disco. Las anclas demo son placeholders de semilla — útiles para probar la UI pero no prueba de cadena independiente. Los chips de filtro te dejan ver cada carril con claridad.',
  'vault.how.step3.title': 'Verifica en tu navegador',
  'vault.how.step3.body': 'Pega un hash de contenido SHA-256, sube un archivo .ots coincidente, o haz clic en «Usar esta prueba» en cualquier tarjeta de programa. MotoPass valida el formato localmente y te enlaza a Satohash para la verificación independiente.',
  'vault.how.step4.title': 'Comparte el linaje de la prueba',
  'vault.how.step4.body': 'Copia un stub de evento Nostr kind:30078 para difundir actualizaciones de programas en tu relay. Combínalo con Solicitar para sellar tu propio hash de solicitud — el mismo pipeline que usan los operadores para la diligencia.',
  'vault.how.footer': 'Solo educativo — no es asesoramiento legal, fiscal ni de inversión. MotoPass no custodia documentos; verificas de forma independiente en Bitcoin.',
  'distressed.how.eyebrow': 'CÓMO FUNCIONA',
  'distressed.how.title': 'Por qué existe Distressed — y cómo fluyen los acuerdos',
  'distressed.how.intro': 'Distressed es el pilar Forge de MotoPass — un mercado bloqueado por prueba para jugadas soberanas subvaloradas, eficientes en capital o estructuralmente interesantes. No es un sitio de listados. Cada fila requiere prueba Satohash antes de aparecer.',
  'distressed.how.step1.title': 'Cómo se construyen los listados',
  'distressed.how.step1.body': 'Solo los programas con profundidad insignia, vías y pruebas Satohash califican. Cada listado muestra una vía, un pedido en ₿ primero, banderas rojas y consejos de optimización extraídos de countries.json en vivo — no texto de marketing estático.',
  'distressed.how.step2.title': 'Curado vs sin permiso',
  'distressed.how.step2.body': 'Carril curado: jugadas mejor puntuadas elegidas por Kimi para el ajuste del operador. Carril sin permiso: misma puerta de prueba, pero comprador precavido — MotoPass coordina inteligencia, no custodia. Ambos carriles requieren proof_url.',
  'distressed.how.step3.title': 'Leer el puntaje distressed',
  'distressed.how.step3.body': 'El puntaje de 1 a 5 clasifica eficiencia de capital y señales de valor — mínimos más bajos, rutas de solvencia, palabras clave presupuestarias y compensaciones de soberanía. Filtra por región, puntaje mín. y pedido máx. para acotar tus candidatos de stack.',
  'distressed.how.step4.title': 'Del listado a la sala de acuerdos',
  'distressed.how.step4.body': 'Abre una tarjeta → verifica la prueba en la Bóveda → revisa la plantilla de depósito en garantía (stub PSBT, sin custodia de fondos) → Solicita o escala a un agente Kimi en la sala. MotoPass nunca tiene tu Bitcoin.',
  'distressed.how.footer': 'Solo depósito en garantía de plantilla. Inteligencia educativa — no asesoramiento legal, fiscal ni de inversión. Haz tu propia diligencia antes de comprometer capital.',
  'distressed.filtersTitle': 'Directorio de listados',
