  'pitch.platform.eyebrow': 'STACK SOBERANO',
  'pitch.platform.title': 'Cuatro pilares. Un solo sistema operativo.',
  'pitch.platform.sub': 'MotoPass es la capa de inteligencia para operadores de alto patrimonio que apilan segunda residencia, ciudadanía y movilidad nativa de Bitcoin — con prueba en cada dato material.',
  'pitch.pillar.seal.title': 'Seal',
  'pitch.pillar.seal.sub': 'OpenTimestamps Satohash sobre datos de programas insignia. Verifica hashes y archivos .ots en la Bóveda.',
  'pitch.pillar.forge.title': 'Forge',
  'pitch.pillar.forge.sub': 'Mercado Distressed para jugadas soberanas bloqueadas por prueba — curado o sin permiso, pedidos en ₿ primero.',
  'pitch.pillar.nexus.title': 'Nexus',
  'pitch.pillar.nexus.sub': 'Identidad nativa Nostr y enrutamiento de relay para solicitudes — sin correo, el npub es tu cuenta.',
  'pitch.pillar.ledger.title': 'Ledger',
  'pitch.pillar.ledger.sub': 'Oráculo de 50 jurisdicciones desde countries.json — compara, simula stacks y modela el costo en tiempo real.',
  'pitch.products.eyebrow': 'PLATAFORMA',
  'pitch.products.title': 'Construido para operadores, no para turistas',
  'pitch.product.programs.title': 'Programas',
  'pitch.product.programs.sub': 'Investiga 50 vías CBI/RBI con finanzas, puntajes de soberanía y preparación Lightning.',
  'pitch.product.vault.title': 'Bóveda',
  'pitch.product.vault.sub': 'Audita pruebas Satohash, sube archivos .ots y verifica anclas en el navegador.',
  'pitch.product.distressed.title': 'Distressed',
  'pitch.product.distressed.sub': 'Listados bloqueados por prueba con pedidos en ₿, plantillas de depósito y carriles curados por Kimi.',
  'pitch.product.apply.title': 'Solicitar',
  'pitch.product.apply.sub': 'Registra interés con un hash sellable — bloqueado por el marcador del Launch Engine.',
  'pitch.how.eyebrow': 'CÓMO FUNCIONA',
  'pitch.how.title': 'De la investigación a la prueba sellada en tres pasos',
  'pitch.how.step1.title': 'Modela tu stack',
  'pitch.how.step1.body': 'Filtra jurisdicciones, ejecuta el simulador de stack y compara tarifas lado a lado — todas las cifras provienen de datos de programas en vivo.',
  'pitch.how.step2.title': 'Verifica cada dato',
  'pitch.how.step2.body': 'Cruza las anclas Satohash en la Bóveda. Sube archivos OpenTimestamps. Sin confianza de folleto.',
  'pitch.how.step3.title': 'Solicita con prueba',
  'pitch.how.step3.body': 'Conecta Nostr, registra interés y sella tu hash de solicitud en Bitcoin para verificación independiente.',
  'pitch.live.eyebrow': 'DATOS EN VIVO',
  'pitch.live.title': 'Esta página se actualiza sola',
  'pitch.live.programs': 'Conteos de programas y ahorros modelados desde countries.json en cada visita',
  'pitch.live.btc': 'Precio spot ₿ desde mempool.space — doble pantalla en todas las cifras monetarias',
  'pitch.live.proofs': 'Las marcas de tiempo de prueba reflejan las últimas fechas last_checked del conjunto de datos',
  'pitch.live.gates': 'Marcador de puertas de lanzamiento sincronizado desde launch-gates.json al desplegar',
  'pitch.faq.eyebrow': 'FAQ',
  'pitch.faq.title': 'Las preguntas que los operadores hacen primero',
  'pitch.ctaBand.title': '¿Listo para apilar con prueba?',
  'pitch.ctaBand.sub': 'Explora jurisdicciones, verifica anclas y registra interés — movilidad soberana sin confianza de folleto.',
  'pitch.ctaBand.apply': 'Abrir solicitudes',
  'pitch.ctaBand.explore': 'Explorar programas',
  'pitch.ctaBand.vault': 'Explorar Bóveda',
  'pitch.faq.q1': '¿Qué es MotoPass?',
  'pitch.faq.a1': 'MotoPass es una plataforma nativa de Bitcoin para evaluar, comparar y apilar programas de residencia y ciudadanía soberanas con datos verificados por Satohash e identidad Nostr.',
  'pitch.faq.q2': '¿Cómo funciona la verificación Satohash?',
  'pitch.faq.a2': 'Los datos materiales se hasean y anclan a Bitcoin vía OpenTimestamps. Cualquiera puede verificar las pruebas de forma independiente en Satohash.io sin confiar en una captura de folleto.',
  'pitch.faq.q3': '¿Necesito correo para solicitar?',
  'pitch.faq.a3': 'No. MotoPass usa registro nativo npub Nostr — conecta tu extensión de navegador y tu clave pública se convierte en tu cuenta.',
  'pitch.faq.q4': '¿Para qué sirve la Bóveda?',
  'pitch.faq.a4': 'La Bóveda es donde auditas las pruebas Satohash — pega un hash de contenido, sube un archivo OpenTimestamps, o elige un programa y verifica anclas en Bitcoin sin confiar en la palabra de MotoPass.',
  'pitch.faq.q5': '¿Qué es Distressed?',
  'pitch.faq.a5': 'Distressed es un mercado bloqueado por prueba para jugadas soberanas eficientes en capital. Los listados requieren prueba Satohash, muestran pedidos en ₿ primero y ofrecen depósito de plantilla más escalada al agente Kimi — MotoPass nunca custodia fondos.',
  'pitch.guide.eyebrow': 'ENTENDER MOTOPASS',
  'pitch.guide.title': 'Una plataforma, cuatro pilares, cero confianza de folleto',
  'pitch.guide.intro': 'MotoPass es el sistema operativo privado para operadores soberanos — investiga jurisdicciones, verifica datos en Bitcoin, rastrea tu stack y coordina vía Nostr. Aquí está el recorrido completo, de izquierda a derecha.',
  'pitch.guide.step1.title': 'Forge — descubre y modela',
  'pitch.guide.step1.body': 'Empieza en Programas: filtra 50 jurisdicciones, ejecuta el simulador de stack, compara tarifas y revisa la densidad de comercios en Mapa BTC. Distressed saca a la superficie jugadas de valor bloqueadas por prueba cuando quieres rutas eficientes en capital.',
  'pitch.guide.step2.title': 'Seal — verifica en Bitcoin',
  'pitch.guide.step2.body': 'Cada dato material debería anclarse a un bloque Bitcoin. La Bóveda te deja pegar hashes, subir archivos .ots y auditar pruebas de forma independiente vía Satohash.io — Verdad que puedes comprobar.',
  'pitch.guide.step3.title': 'Ledger — rastrea tu stack',
  'pitch.guide.step3.body': 'Guarda los programas adquiridos en el Portafolio, modela stacks multi-jurisdiccionales y monitorea puntajes de soberanía, preparación Lightning y cronogramas de renovación desde datos de programas en vivo.',
  'pitch.guide.step4.title': 'Nexus — solicita y coordina',
  'pitch.guide.step4.body': 'Conecta tu npub, registra interés en Solicitar (bloqueado al lanzamiento), sella tu hash de solicitud y escala a los agentes de enlace Kimi — sin correo, sin Salesforce, sin cuerda de terciopelo.',
  'pitch.guide.footer': 'Solo inteligencia educativa — no asesoramiento legal, fiscal, migratorio ni de inversión. Verifica cada dato de forma independiente antes de comprometer capital.',
  'pitch.guide.cta': 'Abrir',
  'pitch.trusted.eyebrow': 'CONFIADO POR OPERADORES EN',
  'pitch.trusted.label': 'Jurisdicciones rastreadas en vivo en MotoPass',
