  'nav.shortcuts.agents': 'Aller aux Agents',
  'nav.shortcuts.footerGap': 'Espace bas de page ? L\'espace mobile vit uniquement sur footer-glass — aucun rembourrage de coquille de mise en page sous le main.',
  'agents.eyebrow': 'AGENTS DE LIAISON',
  'agents.gridTitle': 'Agents de liaison pays (via Kimi)',
  'agents.connectHint': 'Connectez Nostr — Kimi vous oriente vers le bon agent pays',
  'agents.message': 'Message via Nostr',
  'agents.messageSoon': 'Bientôt',
  'agents.disclaimer': 'Les agents de liaison assistent les utilisateurs Nostr vérifiés dans leurs échanges avec les bureaux de passeport officiels. Toutes les orientations d\'agents sont informatives — pas un conseil juridique. Les interactions scellées s\'ancrent à Satohash.',
  'agents.how.eyebrow': 'COMMENT CELA FONCTIONNE',
  'agents.how.title': 'Pourquoi les Agents existent — et comment Nexus coordonne votre stack',
  'agents.how.intro': 'Agents est le pilier Nexus de MotoPass — la couche club où les opérateurs souverains se connectent via Nostr, obtiennent des orientations par pays et escaladent de la recherche à la candidature scellée sans gardiens par e-mail ou brochure.',
  'agents.how.step1.title': 'Connectez votre npub',
  'agents.how.step1.body': 'MotoPass est Nostr-natif. Connectez votre extension de navigateur (Alby, nos2x, etc.) et votre clé publique devient votre identité sur Postuler, Agents et les futurs relays du club — sans inscription par e-mail.',
  'agents.how.step2.title': 'Kimi orchestre, les agents pays conseillent',
  'agents.how.step2.body': 'Kimi est votre liaison stratégique sur M4 HERMES — elle vous oriente vers des agents spécialisés par juridiction (Uruguay, El Salvador, EAU, et plus) formés sur les données de programmes fleurons et les exigences de preuve Satohash.',
  'agents.how.step3.title': 'Message avec contexte de preuve',
  'agents.how.step3.body': 'Chaque carte d\'agent ouvre un stub de DM Nostr (kind:14) pré-rempli avec le contexte du programme. Associez-le à la vérification du Coffre et aux annonces Distressed pour que chaque conversation référence des données vérifiables indépendamment.',
  'agents.how.step4.title': 'Escaladez de l\'intérêt à la candidature',
  'agents.how.step4.body': 'Enregistrez votre intérêt sur Postuler (verrouillé au lancement), scellez votre hachage de candidature sur Bitcoin, puis revenez ici pour coordonner la préparation des documents, l\'optimisation de parcours et les transferts de conseil via Nostr.',
  'agents.how.footer': 'L\'orientation des agents est une intelligence pédagogique — pas un conseil juridique, fiscal, d\'immigration ou d\'investissement. Vérifiez chaque donnée sur Bitcoin avant d\'engager du capital.',
  'agents.nexus.title': 'Nexus souverain d\'élite',
  'agents.nexus.sub': 'Identité Nostr · orchestration Kimi · rails BTC/Lightning · coordination de club sans cordon de velours',
  'agents.paige.title': 'Concierge IA Paige',
  'agents.paige.body': 'Posez des questions sur les juridictions, fondées sur countries.json. Paige cite les IDs de preuve Satohash quand ils sont disponibles et signale honnêtement les champs non vérifiés. Elle escalade à Kimi ou aux agents pays quand un jugement humain est nécessaire.',
  'agents.dealroom.title': 'Escalade en salle de deal',
  'agents.dealroom.body': 'Depuis les annonces Distressed, ouvrez un fil de salle de deal pour escalader à Kimi avec le contexte de preuve, les notes de modèle d\'escrow et les drapeaux rouges de parcours — MotoPass coordonne l\'intelligence, jamais la garde.',
