  'pitch.platform.eyebrow': 'STACK SOBERANO',
  'pitch.platform.title': 'Quatro pilares. Um sistema operativo.',
  'pitch.platform.sub': 'O MotoPass é a camada de inteligência para operadores de alto património que empilham segunda residência, cidadania e mobilidade nativa de Bitcoin — com prova em cada alegação material.',
  'pitch.pillar.seal.title': 'Seal',
  'pitch.pillar.seal.sub': 'OpenTimestamps Satohash nos dados de programas emblemáticos. Verifique hashes e ficheiros .ots no Cofre.',
  'pitch.pillar.forge.title': 'Forge',
  'pitch.pillar.forge.sub': 'Mercado Distressed para jogadas soberanas bloqueadas por prova — selecionado ou sem permissão, pedidos em ₿ primeiro.',
  'pitch.pillar.nexus.title': 'Nexus',
  'pitch.pillar.nexus.sub': 'Identidade nativa Nostr e roteamento de relay para candidaturas — sem e-mail, o npub é a sua conta.',
  'pitch.pillar.ledger.title': 'Ledger',
  'pitch.pillar.ledger.sub': 'Oracle de 50 jurisdições de countries.json — compare, simule stacks e modele custos em tempo real.',
  'pitch.products.eyebrow': 'PLATAFORMA',
  'pitch.products.title': 'Construído para operadores, não para turistas',
  'pitch.product.programs.title': 'Programas',
  'pitch.product.programs.sub': 'Pesquise 50 vias CBI/RBI com finanças, pontuações de soberania e preparação Lightning.',
  'pitch.product.vault.title': 'Cofre',
  'pitch.product.vault.sub': 'Audite provas Satohash, carregue ficheiros .ots e verifique âncoras no navegador.',
  'pitch.product.distressed.title': 'Distressed',
  'pitch.product.distressed.sub': 'Listagens bloqueadas por prova com pedidos em ₿, modelos de escrow e vias selecionadas pela Kimi.',
  'pitch.product.apply.title': 'Candidatar-se',
  'pitch.product.apply.sub': 'Registe interesse com um hash selável — bloqueado pelo marcador do Launch Engine.',
  'pitch.how.eyebrow': 'COMO FUNCIONA',
  'pitch.how.title': 'Da pesquisa à prova selada em três movimentos',
  'pitch.how.step1.title': 'Modele o seu stack',
  'pitch.how.step1.body': 'Filtre jurisdições, execute o simulador de stack e compare taxas lado a lado — todos os números vêm de dados de programa ao vivo.',
  'pitch.how.step2.title': 'Verifique cada alegação',
  'pitch.how.step2.body': 'Cruze âncoras Satohash no Cofre. Carregue ficheiros OpenTimestamps. Sem confiança de brochura.',
  'pitch.how.step3.title': 'Candidate-se com prova',
  'pitch.how.step3.body': 'Ligue Nostr, registe interesse e carimbe o seu hash de candidatura em Bitcoin para verificação independente.',
  'pitch.live.eyebrow': 'DADOS AO VIVO',
  'pitch.live.title': 'Esta página atualiza-se sozinha',
  'pitch.live.programs': 'Contagens de programas e poupanças modeladas a partir de countries.json em cada visita',
  'pitch.live.btc': 'Preço spot ₿ de mempool.space — dupla exibição em todos os valores monetários',
  'pitch.live.proofs': 'Os carimbos de tempo de prova refletem as últimas datas last_checked do conjunto de dados',
  'pitch.live.gates': 'Marcador de gates de lançamento sincronizado de launch-gates.json no deploy',
  'pitch.faq.eyebrow': 'FAQ',
  'pitch.faq.title': 'As perguntas que os operadores fazem primeiro',
  'pitch.ctaBand.title': 'Pronto para empilhar com prova?',
  'pitch.ctaBand.sub': 'Explore jurisdições, verifique âncoras e registe interesse — mobilidade soberana sem confiança de brochura.',
  'pitch.ctaBand.apply': 'Abrir candidaturas',
  'pitch.ctaBand.explore': 'Navegar pelos programas',
  'pitch.ctaBand.vault': 'Explorar Cofre',
  'pitch.faq.q1': 'O que é o MotoPass?',
  'pitch.faq.a1': 'O MotoPass é uma plataforma nativa de Bitcoin para avaliar, comparar e empilhar programas soberanos de residência e cidadania com dados verificados por Satohash e identidade Nostr.',
  'pitch.faq.q2': 'Como funciona a verificação Satohash?',
  'pitch.faq.a2': 'Alegações materiais são hasheadas e ancoradas em Bitcoin via OpenTimestamps. Qualquer pessoa pode verificar as provas de forma independente no Satohash.io sem confiar num instantâneo de brochura.',
  'pitch.faq.q3': 'Preciso de e-mail para me candidatar?',
  'pitch.faq.a3': 'Não. O MotoPass usa registo nativo npub Nostr — ligue a sua extensão de navegador e a sua chave pública torna-se a sua conta.',
  'pitch.faq.q4': 'Para que serve o Cofre?',
  'pitch.faq.a4': 'O Cofre é onde audita provas Satohash — cole um hash de conteúdo, carregue um ficheiro OpenTimestamps, ou escolha um programa e verifique âncoras em Bitcoin sem confiar na palavra do MotoPass.',
  'pitch.faq.q5': 'O que é o Distressed?',
  'pitch.faq.a5': 'Distressed é um mercado bloqueado por prova para jogadas soberanas eficientes em capital. As listagens exigem prova Satohash, mostram pedidos em ₿ primeiro e oferecem escrow de modelo mais escalação a agente Kimi — o MotoPass nunca guarda fundos.',
  'pitch.guide.eyebrow': 'COMPREENDER O MOTOPASS',
  'pitch.guide.title': 'Uma plataforma, quatro pilares, zero confiança de brochura',
  'pitch.guide.intro': 'O MotoPass é o sistema operativo privado para operadores soberanos — pesquise jurisdições, verifique alegações em Bitcoin, acompanhe o seu stack e coordene via Nostr. Aqui está a jornada completa, da esquerda para a direita.',
  'pitch.guide.step1.title': 'Forge — descobrir e modelar',
  'pitch.guide.step1.body': 'Comece em Programas: filtre 50 jurisdições, execute o simulador de stack, compare taxas e verifique a densidade de comerciantes no Mapa BTC. Distressed traz à tona jogadas de valor bloqueadas por prova quando quer rotas eficientes em capital.',
  'pitch.guide.step2.title': 'Seal — verificar no Bitcoin',
  'pitch.guide.step2.body': 'Cada alegação material deveria ancorar-se num bloco Bitcoin. O Cofre permite-lhe colar hashes, carregar ficheiros .ots e auditar provas de forma independente via Satohash.io — Verdade que pode verificar.',
  'pitch.guide.step3.title': 'Ledger — acompanhar o seu stack',
  'pitch.guide.step3.body': 'Guarde programas adquiridos no Portfólio, modele stacks multi-jurisdicionais e monitorize pontuações de soberania, preparação Lightning e cronogramas de renovação a partir de dados de programa ao vivo.',
  'pitch.guide.step4.title': 'Nexus — candidatar-se e coordenar',
  'pitch.guide.step4.body': 'Ligue o seu npub, registe interesse em Candidatar-se (bloqueado ao lançamento), carimbe o seu hash de candidatura e escale para os agentes de ligação Kimi — sem e-mail, sem Salesforce, sem corda de veludo.',
  'pitch.guide.footer': 'Apenas inteligência educativa — não aconselhamento jurídico, fiscal, de imigração ou de investimento. Verifique cada alegação de forma independente antes de comprometer capital.',
  'pitch.guide.cta': 'Abrir',
  'pitch.trusted.eyebrow': 'CONFIADO POR OPERADORES EM',
