  'btcmap.intro': 'O MotoPass cruza programas de residência com o BTC Map — o mapa comunitário aberto de comerciantes, comunidades e locais prontos para Lightning que aceitam Bitcoin. Dados de api.btcmap.org; mapa alimentado por btcmap.org.',
