  'agents.disclaimer': 'يساعد وكلاء التواصل مستخدمي Nostr الموثقين في محادثات مكاتب جوازات السفر الرسمية. كل توجيه من الوكلاء إعلامي — وليس نصيحة قانونية. التفاعلات المختومة تُرسى على Satohash.',
  'agents.how.eyebrow': 'كيف يعمل',
  'agents.how.title': 'لماذا يوجد الوكلاء — وكيف ينسّق Nexus محفظتك',
  'agents.how.intro': 'الوكلاء هم ركن Nexus في MotoPass — طبقة النادي حيث يتصل المشغّلون السياديون عبر Nostr، ويتلقون توجيهاً خاصاً بكل دولة، ويصعدون من البحث إلى طلب مختوم بلا حرّاس بريد أو نشرات.',
  'agents.how.step1.title': 'اربط npub الخاص بك',
