  'pitch.ctaBand.vault': 'استكشف الخزنة',
  'pitch.faq.q1': 'ما هو MotoPass؟',
  'pitch.faq.a1': 'MotoPass منصة أصلية بالبيتكوين لتقييم ومقارنة وتراصّ برامج الإقامة والجنسية السيادية ببيانات موثقة Satohash وهوية Nostr.',
  'pitch.faq.q2': 'كيف يعمل تحقق Satohash؟',
  'pitch.faq.a2': 'تُجزَّأ الادعاءات الجوهرية وتُرسى على بيتكوين عبر OpenTimestamps. يمكن لأي شخص التحقق من الأدلة بشكل مستقل على Satohash.io دون الثقة في لقطة نشرة.',
  'pitch.faq.q3': 'هل أحتاج بريداً إلكترونياً للتقديم؟',
  'pitch.faq.a3': 'لا. يستخدم MotoPass تسجيلاً أصلياً بـ npub Nostr — اربط إضافة متصفحك ويصبح مفتاحك العام حسابك.',
  'pitch.faq.q4': 'لأي غرض الخزنة؟',
  'pitch.faq.a4': 'الخزنة حيث تدقّق أدلة Satohash — الصق هاش محتوى أو ارفع ملف OpenTimestamps أو اختر برنامجاً وتحقق من الإرساء على بيتكوين دون الثقة بكلام MotoPass.',
  'pitch.faq.q5': 'ما هي المتعثرة؟',
  'pitch.faq.a5': 'المتعثرة سوق محمية بالإثبات للصفقات السيادية الفعّالة رأس المال. تتطلب القوائم إثبات Satohash وتعرض طلبات بالـ ₿ أولاً وتقدم ضماناً بنموذجاً وتصعيداً إلى وكيل Kimi — لا يمسك MotoPass الأموال أبداً.',
  'pitch.guide.eyebrow': 'فهم MotoPass',
  'pitch.guide.title': 'منصة واحدة وأربعة أركان وصفر ثقة بالنشرات',
  'pitch.guide.intro': 'MotoPass هو نظام التشغيل الخاص للمشغّلين السياديين — ابحث في الاختصاصات وتحقق من الادعاءات على بيتكوين وتتبع محفظتك ونسّق عبر Nostr. إليك الرحلة الكاملة من اليسار إلى اليمين.',
  'pitch.guide.step1.title': 'Forge — اكتشف ونمذج',
  'pitch.guide.step1.body': 'ابدأ في البرامج: صفِّ 50 اختصاصاً وشغّل محاكي المحفظة وقارن الرسوم وافحص كثافة تجار خريطة BTC. تُظهر المتعثرة صفقات القيمة المحمية بالإثبات عندما تريد مسارات فعّالة رأس المال.',
  'pitch.guide.step2.title': 'Seal — تحقق على بيتكوين',
  'pitch.guide.step2.body': 'يجب أن يُرسى كل ادعاء جوهري على بلوك بيتكوين. تتيح لك الخزنة لصق الهاشات ورفع ملفات .ots ودقّق الأدلة بشكل مستقل عبر Satohash.io — حقيقة يمكنك التحقق منها.',
  'pitch.guide.step3.title': 'Ledger — تتبع محفظتك',
  'pitch.guide.step3.body': 'احفظ البرامج المكتسبة في المحفظة ونمذج محافظ متعددة الاختصاصات وراقب درجات السيادة وجاهزية Lightning وجداول التجديد من بيانات البرامج الحية.',
  'pitch.guide.step4.title': 'Nexus — قدّم ونسّق',
  'pitch.guide.step4.body': 'اربط npub الخاص بك وسجّل اهتمامك في تقدّم (محكوم بالإطلاق) واختم هاش طلبك وصعد إلى وكلاء التواصل Kimi — بلا بريد وبلا Salesforce وبلا حبل مخمل.',
  'pitch.guide.footer': 'ذكاء تعليمي فقط — وليس نصيحة قانونية أو ضريبية أو هجرة أو استثمار. تحقق من كل ادعاء بشكل مستقل قبل الالتزام برأس المال.',
