  'distressed.how.footer': 'ضمان قالب فقط. استخبارات تعليمية — ليست نصيحة قانونية أو ضريبية أو استثمارية. أجرِ العناية الواجبة المستقلة قبل الالتزام برأس المال.',
  'distressed.how.intro': 'المتعثرة هي ركيزة الصياغة في MotoPass — سوق محكوم بالإثبات لصفقات سيادية مقوّمة بأقل من قيمتها أو كفؤة رأسمالياً أو مثيرة بنيوياً. ليست موقع قوائم. كل صف يتطلب إثبات Satohash قبل ظهوره.',
  'distressed.how.step1.body': 'تتأهل البرامج ذات العمق الرائد فقط، مع المسارات وإثباتات Satohash. تعرض كل قائمة مساراً واحداً وطلباً أولاً بالـ ₿ وعلامات تحذير ونصائح تحسين مستمدة من countries.json الحيّ — لا نصوص تسويقية ثابتة.',
  'distressed.how.step1.title': 'كيف تُبنى القوائم',
  'distressed.how.step2.body': 'المسار المنتقى: صفقات عالية الدرجات اختارها Kimi يدوياً لملاءمة المشغّلين. المسار غير المرخَّص: بوابة الإثبات نفسها، لكن حذارِ المشتري — ينسّق MotoPass الاستخبارات لا الحفظ. يتطلب المساران proof_url.',
  'distressed.how.step2.title': 'المنتقاة مقابل غير المرخَّصة',
  'distressed.how.step3.body': 'الدرجة من 1 إلى 5 ترتّب كفاءة رأس المال وإشارات القيمة — حد أدنى أقل ومسارات ملاءة وكلمات ميزانية ومقايضات سيادة. صفِّ حسب المنطقة والحد الأدنى للدرجة والحد الأقصى للطلب لتضييق مرشّحي محفظتك.',
  'distressed.how.step3.title': 'قراءة درجة المتعثرة',
  'distressed.how.step4.body': 'افتح بطاقة ← تحقق من الإثبات في الخزنة ← راجع قالب الضمان (نموذج PSBT، دون حفظ أموال) ← قدّم أو صعّد إلى وكيل Kimi في غرفة الصفقة. لا يحتفظ MotoPass بعملاتك أبداً.',
