  'nav.shortcuts.footerGap': 'Pengo la footer? Nafasi ya simu iko kwenye footer-glass pekee — hakuna ujazaji wa shell ya muundo chini ya main.',
  'agents.eyebrow': 'MAWAKALA WA MAWASILIANO',
  'agents.gridTitle': 'Mawakala wa mawasiliano wa nchi (kupitia Kimi)',
  'agents.connectHint': 'Unganisha Nostr — Kimi anakuelekeza kwa wakala sahihi wa nchi',
  'agents.message': 'Tuma ujumbe kupitia Nostr',
  'agents.messageSoon': 'Inakuja hivi karibuni',
  'agents.disclaimer': 'Mawakala wa mawasiliano husaidia watumiaji wa Nostr waliodhibitishwa kwenye mazungumzo na ofisi rasmi za pasipoti. Mwongozo wote wa mawakala ni wa taarifa — si ushauri wa kisheria. Mahusiano yaliyofungwa yanafungwa kwenye Satohash.',
  'agents.how.eyebrow': 'INAVYOFANYA KAZI',
  'agents.how.title': 'Kwa nini Mawakala wapo — na jinsi Nexus inavyoratibu stack yako',
  'agents.how.intro': 'Mawakala ni nguzo ya Nexus ya MotoPass — safu ya klabu ambapo waendeshaji huru wanaungana kupitia Nostr, wanapata mwongozo wa nchi maalum, na wanapanda kutoka utafiti hadi ombi lililofungwa bila walinzi wa barua pepe au brosha.',
  'agents.how.step1.title': 'Unganisha npub yako',
  'agents.how.step1.body': 'MotoPass ni asilia Nostr. Unganisha kiendelezi cha kivinjari (Alby, nos2x, n.k.) na ufunguo wako wa umma unakuwa utambulisho wako katika Omba, Mawakala na relay za baadaye za klabu — bila usajili wa barua pepe.',
  'agents.how.step2.title': 'Kimi anaratibu, mawakala wa nchi wanashauri',
  'agents.how.step2.body': 'Kimi ni mwasiliani wako wa kimkakati kwenye M4 HERMES — anakuelekeza kwa mawakala wa mamlaka maalum (Uruguay, El Salvador, UAE, na zaidi) waliofunzwa kwenye data ya programu za mfano na mahitaji ya uthibitisho wa Satohash.',
  'agents.how.step3.title': 'Tuma ujumbe kwa muktadha wa uthibitisho',
  'agents.how.step3.body': 'Kila kadi ya wakala inafungua kigae cha DM cha Nostr (kind:14) kilichojazwa awali kwa muktadha wa programu. Unganisha na uthibitisho wa Kuba na orodha za Tatizo ili kila mazungumzo yarejelee madai yanayoweza kuthibitishwa kwa uhuru.',
  'agents.how.step4.title': 'Panda kutoka nia hadi ombi',
  'agents.how.step4.body': 'Andika nia kwenye Omba (imezuiwa kwa uzinduzi), funga hashi ya ombi lako kwenye Bitcoin, kisha rudi hapa kuratibu maandalizi ya nyaraka, uboreshaji wa njia na kukabidhi ushauri kupitia Nostr.',
  'agents.how.footer': 'Mwongozo wa wakala ni akili ya elimu — si ushauri wa kisheria, kodi, uhamiaji au uwekezaji. Thibitisha kila dai kwenye Bitcoin kabla ya kuwekeza mtaji.',
  'agents.nexus.title': 'Nexus ya Kiheshimiwa Huru',
  'agents.nexus.sub': 'Utambulisho wa Nostr · uratibu wa Kimi · reli za BTC/Lightning · uratibu wa klabu bila kamba ya velvet',
  'agents.paige.title': 'Paige mhudumu wa AI',
  'agents.paige.body': 'Uliza maswali ya mamlaka yanayotegemea countries.json. Paige anataja ID za uthibitisho wa Satohash zinapopatikana na kuweka alama kwa uaminifu nyanja zisizothibitishwa. Anapanda kwa Kimi au mawakala wa nchi kunapohitajika uamuzi wa kibinadamu.',
  'agents.dealroom.title': 'Upandaji wa chumba cha mikataba',
  'agents.dealroom.body': 'Kutoka orodha za Tatizo, fungua mada ya chumba cha mikataba kupanda kwa Kimi kwa muktadha wa uthibitisho, maelezo ya mfano wa escrow na bendera nyekundu za njia — MotoPass inaratibu akili, kamwe haishiki mali.',
