  'pitch.platform.eyebrow': 'STACK HURU',
  'pitch.platform.title': 'Nguzo nne. Mfumo mmoja wa uendeshaji.',
  'pitch.platform.sub': 'MotoPass ni safu ya akili kwa waendeshaji wenye utajiri mkubwa wanaorundika ukaaji wa pili, uraia na uhamaji asilia wa Bitcoin — kwa uthibitisho kwenye kila dai la msingi.',
  'pitch.pillar.seal.title': 'Seal',
  'pitch.pillar.seal.sub': 'Satohash OpenTimestamps kwenye data ya programu za mfano. Thibitisha hashi na faili za .ots kwenye Kuba.',
  'pitch.pillar.forge.title': 'Forge',
  'pitch.pillar.forge.sub': 'Soko la Tatizo la michezo huru iliyolindwa na uthibitisho — iliyochaguliwa au isiyoidhinishwa, maombi ya ₿ kwanza.',
  'pitch.pillar.nexus.title': 'Nexus',
  'pitch.pillar.nexus.sub': 'Utambulisho asilia wa Nostr na njia za relay kwa maombi — bila barua pepe, npub ndiyo akaunti yako.',
  'pitch.pillar.ledger.title': 'Ledger',
  'pitch.pillar.ledger.sub': 'Mtabiri wa mamlaka 50 kutoka countries.json — linganisha, igiza stacks na tengeneza gharama kwa wakati halisi.',
  'pitch.products.eyebrow': 'JUKWAA',
  'pitch.products.title': 'Imejengwa kwa waendeshaji, si kwa watalii',
  'pitch.product.programs.title': 'Programu',
  'pitch.product.programs.sub': 'Chunguza njia 50 za CBI/RBI kwa fedha, alama za uhuru na utayari wa Lightning.',
  'pitch.product.vault.title': 'Kuba',
  'pitch.product.vault.sub': 'Kaguo uthibitisho wa Satohash, pakia faili za .ots na uthibitishe kufungwa kwenye kivinjari.',
  'pitch.product.distressed.title': 'Tatizo',
  'pitch.product.distressed.sub': 'Orodha zilizolindwa na uthibitisho kwa maombi ya ₿, violezo vya escrow na njia zilizochaguliwa na Kimi.',
  'pitch.product.apply.title': 'Omba',
  'pitch.product.apply.sub': 'Andika nia kwa hashi inayoweza kufungwa — imezuiwa na kadi ya alama ya Injini ya Uzinduzi.',
  'pitch.how.eyebrow': 'INAVYOFANYA KAZI',
  'pitch.how.title': 'Kutoka utafiti hadi uthibitisho uliofungwa kwa hatua tatu',
  'pitch.how.step1.title': 'Tengeneza stack yako',
  'pitch.how.step1.body': 'Chuja mamlaka, endesha kiigizo cha stack na linganisha ada upande kwa upande — takwimu zote kutoka data ya programu za moja kwa moja.',
  'pitch.how.step2.title': 'Thibitisha kila dai',
  'pitch.how.step2.body': 'Angalia kwa makini kufungwa kwa Satohash kwenye Kuba. Pakia faili za OpenTimestamps. Hakuna haja ya kuamini brosha.',
  'pitch.how.step3.title': 'Omba kwa uthibitisho',
  'pitch.how.step3.body': 'Unganisha Nostr, andika nia na funga hashi ya ombi lako kwenye Bitcoin kwa uthibitisho huru.',
  'pitch.live.eyebrow': 'DATA YA MOJA KWA MOJA',
  'pitch.live.title': 'Ukurasa huu unajisasisha',
  'pitch.live.programs': 'Hesabu za programu na uokoaji vinatengenezwa kutoka countries.json kila ziara',
  'pitch.live.btc': 'Bei ya spot ₿ kutoka mempool.space — onyesho maradufu kwenye takwimu zote za fedha',
  'pitch.live.proofs': 'Mihuri ya uthibitisho inaonyesha tarehe za mwisho za last_checked kwenye seti ya data',
  'pitch.live.gates': 'Kadi ya alama ya milango ya uzinduzi imesawazishwa kutoka launch-gates.json kwenye uwekaji',
  'pitch.faq.eyebrow': 'MASWALI',
  'pitch.faq.title': 'Maswali waendeshaji huuliza kwanza',
  'pitch.ctaBand.title': 'Tayari kurundika kwa uthibitisho?',
  'pitch.ctaBand.sub': 'Chunguza mamlaka, thibitisha kufungwa na andika nia — uhamaji huru bila kuamini brosha.',
  'pitch.ctaBand.apply': 'Fungua maombi',
  'pitch.ctaBand.explore': 'Vinjari programu',
  'pitch.ctaBand.vault': 'Chunguza Kuba',
  'pitch.faq.q1': 'MotoPass ni nini?',
  'pitch.faq.a1': 'MotoPass ni jukwaa asilia la Bitcoin la kutathmini, kulinganisha na kurundika programu huru za ukaaji na uraia kwa data iliyothibitishwa na Satohash na utambulisho wa Nostr.',
  'pitch.faq.q2': 'Uthibitishaji wa Satohash unafanyaje kazi?',
  'pitch.faq.a2': 'Madai ya msingi yanahashishwa na kufungwa kwenye Bitcoin kupitia OpenTimestamps. Mtu yeyote anaweza kuthibitisha uthibitisho kwa uhuru kwenye Satohash.io bila kuamini picha ya brosha.',
  'pitch.faq.q3': 'Ninahitaji barua pepe kuomba?',
  'pitch.faq.a3': 'Hapana. MotoPass inatumia usajili asilia wa npub Nostr — unganisha kiendelezi cha kivinjari na ufunguo wako wa umma unakuwa akaunti yako.',
  'pitch.faq.q4': 'Kuba ni ya nini?',
  'pitch.faq.a4': 'Kuba ni mahali unapokagua uthibitisho wa Satohash — bandika hashi ya maudhui, pakia faili ya OpenTimestamps, au chagua programu na uthibitishe kufungwa kwenye Bitcoin bila kuamini maneno ya MotoPass.',
  'pitch.faq.q5': 'Tatizo ni nini?',
  'pitch.faq.a5': 'Tatizo ni soko lililolindwa na uthibitisho kwa michezo huru ya ufanisi wa mtaji. Orodha zinahitaji uthibitisho wa Satohash, zinaonyesha maombi ya ₿ kwanza na kutoa escrow ya kiolezo pamoja na upandaji wa wakala wa Kimi — MotoPass kamwe haishiki fedha.',
  'pitch.guide.eyebrow': 'KUELEWA MOTOPASS',
  'pitch.guide.title': 'Jukwaa moja, nguzo nne, sifuri kuamini brosha',
  'pitch.guide.intro': 'MotoPass ni mfumo wa uendeshaji wa faragha kwa waendeshaji huru — chunguza mamlaka, thibitisha madai kwenye Bitcoin, fuatilia stack yako na uratibu kupitia Nostr. Huu ni mwongozo kamili, kutoka kushoto kwenda kulia.',
  'pitch.guide.step1.title': 'Forge — gundua na tengeneza',
  'pitch.guide.step1.body': 'Anza kwenye Programu: chuja mamlaka 50, endesha kiigizo cha stack, linganisha ada na kagua msongamano wa wafanyabiashara wa Ramani ya BTC. Tatizo linaonyesha michezo ya thamani iliyolindwa na uthibitisho unapotaka njia za ufanisi wa mtaji.',
  'pitch.guide.step2.title': 'Seal — thibitisha kwenye Bitcoin',
  'pitch.guide.step2.body': 'Kila dai la msingi linapaswa kufungwa kwenye block ya Bitcoin. Kuba inakuwezesha kubandika hashi, kupakia faili za .ots na kukagua uthibitisho kwa uhuru kupitia Satohash.io — Ukweli Unaoweza Kuthibitisha.',
  'pitch.guide.step3.title': 'Ledger — fuatilia stack yako',
  'pitch.guide.step3.body': 'Hifadhi programu zilizopatikana kwenye Kwingineko, tengeneza stacks za mamlaka nyingi na fuatilia alama za uhuru, utayari wa Lightning na ratiba za upyaji kutoka data ya programu za moja kwa moja.',
  'pitch.guide.step4.title': 'Nexus — omba na uratibu',
  'pitch.guide.step4.body': 'Unganisha npub yako, andika nia kwenye Omba (imezuiwa kwa uzinduzi), funga hashi ya ombi lako na panda kwa mawakala wa mawasiliano wa Kimi — bila barua pepe, bila Salesforce, bila kamba ya velvet.',
  'pitch.guide.footer': 'Akili ya elimu pekee — si ushauri wa kisheria, kodi, uhamiaji au uwekezaji. Thibitisha kila dai kwa uhuru kabla ya kuwekeza mtaji.',
  'pitch.guide.cta': 'Fungua',
