  'btcmap.intro': 'MotoPass inalinganisha programu za ukaaji na Ramani ya BTC — ramani ya jamii iliyo wazi ya wafanyabiashara, jamii na kumbi tayari za Lightning zinazokubali Bitcoin. Data kutoka api.btcmap.org; ramani inaendeshwa na btcmap.org.',
