  'distressed.filterSheetApply': 'Onyesha orodha ({count} hai)',
  'distressed.filterSheetOpen': 'Vichujio',
  'distressed.filterSheetTitle': 'Vichujio vya orodha',
  'distressed.filteredOfTotal': '{shown} kati ya {total} kwa jumla',
  'distressed.filtersActive': 'vichujio {count}',
  'distressed.filtersSub': 'Chuja kwa njia, eneo na alama — tafuta programu na njia',
  'distressed.filtersTitle': 'Orodha ya matangazo',
  'distressed.gateExplainerLink': 'Kwa nini orodha zimefungwa — soma kadi ya alama ya lango la Uzinduzi',
  'distressed.how.eyebrow': 'JINSI INVYOFANYA KAZI',
  'distressed.how.footer': 'Escrow ya mfano pekee. Taarifa za kielimu — si ushauri wa kisheria, kodi, au uwekezaji. Fanya uchunguzi wa kujitegemea kabla ya kuweka mtaji.',
  'distressed.how.intro': 'Distressed ni nguzo ya Forge ya MotoPass — soko linalohitaji uthibitisho kwa mikakati huru ambayo haijathaminiwa, inayotumia mtaji kwa ufanisi, au yenye mvuto wa kimuundo. Si tovuti ya matangazo. Kila safu inahitaji uthibitisho wa Satohash kabla ya kuonekana.',
  'distressed.how.step1.body': 'Programu zenye kina cha kipekee zilizo na njia na uthibitisho wa Satohash pekee ndizo zinazostahili. Kila orodha inaonyesha njia moja, ombi la ₿-kwanza, alama nyekundu, na vidokezo vya uboreshaji kutoka countries.json ya moja kwa moja — si maandishi tuli ya uuzaji.',
  'distressed.how.step1.title': 'Jinsi orodha zinavyojengwa',
  'distressed.how.step2.body': 'Njia iliyochaguliwa: mikakati yenye alama za juu iliyochaguliwa na Kimi kwa wendeshaji. Njia isiyoidhinishwa: lango lile lile la uthibitisho, lakini mnunuzi ajihadhari — MotoPass inaratibu taarifa, si uhifadhi. Njia zote mbili zinahitaji proof_url.',
  'distressed.how.step2.title': 'Iliyochaguliwa dhidi ya isiyoidhinishwa',
  'distressed.how.step3.body': 'Alama 1–5 inapanga ufanisi wa mtaji na ishara za thamani — viwango vya chini, njia za ufilisi, maneno muhimu ya bajeti, na mabadilishano ya uhuru. Chuja kwa eneo, alama ya chini na ombi la juu zaidi ili kupunguza wagombea wa stack yako.',
  'distressed.how.step3.title': 'Kusoma alama ya distressed',
  'distressed.how.step4.body': 'Fungua kadi → thibitisha uthibitisho kwenye Kuba → kagua mfano wa escrow (PSBT stub, hakuna uhifadhi wa fedha) → Omba au ongeza kwa wakala wa Kimi kwenye chumba cha makubaliano. MotoPass kamwe haishiki Bitcoin yako.',
  'distressed.how.step4.title': 'Kutoka orodha hadi chumba cha makubaliano',
  'distressed.how.title': 'Kwa nini Distressed ipo — na jinsi makubaliano yanavyotiririka',
  'distressed.kimiAgentsLink': 'Kutana na mawakala wa Kimi',
  'distressed.kimiCurated': 'Iliyochaguliwa na Kimi',
  'distressed.kimiCuratedTooltip': 'Njia iliyochaguliwa na Kimi — proof_url inahitajika, alama ya distressed ≥4. Ongeza kwa Mawakala kwa msaada wa chumba cha makubaliano.',
  'distressed.kimiGold': 'Dhahabu ya Kimi',
  'distressed.kimiGoldTooltip': 'Uchaguzi wa dhahabu wa Kimi — kina cha kipekee, uthibitisho wa moja kwa moja wa Satohash, na alama ya distressed ≥4. Njia ya juu zaidi inayohitaji uthibitisho.',
