  'vault.doc.confirmedBlock': 'Block {block}',
  'vault.doc.copyHash': 'Nakili hash ya maudhui',
  'vault.doc.delete': 'Ondoa kwenye sajili',
  'vault.doc.dropDescription': 'Hash inabaki ndani — SHA-256 pekee hutumwa kwa Satohash',
  'vault.doc.dropTitle': 'Dondosha faili hapa (au bofya kuvinjari)',
  'vault.doc.pick': 'Chagua nyaraka za kufunga muhuri',
  'vault.doc.privacyNote': 'Faili kamwe hazipakiwi wala kuhifadhiwa — hash pekee ndiyo hufungwa muhuri. Muhuri uliothibitishwa unathibitisha faili hii haswa ilikuwepo kwenye block hiyo ya Bitcoin. Sajili hii inahifadhiwa kwenye kifaa hiki pekee.',
  'vault.doc.refresh': 'Angalia tena hali ya nanga',
  'vault.doc.stamping': 'Inahesabu hash na kufunga muhuri',
  'vault.doc.status.confirmed': 'Imethibitishwa',
  'vault.doc.status.error': 'Hitilafu',
  'vault.doc.status.pending': 'Inasubiri',
  'vault.doc.subtitle': 'Dondosha faili yoyote (skana ya pasipoti, mkataba, ombi) — inahesabiwa hash ndani na SHA-256 inafungwa kwenye Bitcoin kupitia API ya Satohash. Faili lenyewe kamwe halitoki kwenye kifaa hiki.',
  'vault.doc.title': 'Funga muhuri nyaraka zako mwenyewe',
  'vault.doc.verify': 'Thibitisha kwenye Satohash',
  'vault.educationBody': 'Maelezo mafupi ya kuhesabu hash ya data ya programu, kupakia risiti za .ots, na kuthibitisha nanga kwenye Bitcoin — video itatolewa katika BUILD ijayo.',
  'vault.educationEyebrow': 'Elimu ya Kuba',
  'vault.educationStub': 'Tazama maelezo (inakuja hivi karibuni)',
  'vault.educationStubHint': 'Pahala pa video — maelezo ya kamera',
  'vault.educationTitle': 'Jinsi uthibitisho wa OpenTimestamps unavyofanya kazi',
