  'vault.eyebrow': 'KUBA YA UTAFITI',
  'vault.filterAll': 'Zote',
  'vault.filterCount': 'uthibitisho {count}',
  'vault.filterDemo': 'Onyesho',
  'vault.filterTabs': 'Vichujio vya kumbukumbu ya uthibitisho',
  'vault.filterVerified': 'Kwenye faili',
  'vault.hashLabel': 'Hash ya maudhui',
  'vault.how.eyebrow': 'JINSI INVYOFANYA KAZI',
  'vault.how.footer': 'Kielimu pekee — si ushauri wa kisheria, kodi, au uwekezaji. MotoPass haihifadhi nyaraka; unathibitisha kwa kujitegemea kwenye Bitcoin.',
  'vault.how.intro': 'Kuba ni nguzo ya Seal ya MotoPass. Kila dai muhimu la programu linapaswa kubeba cheti cha kuzaliwa cha Bitcoin. Ukurasa huu unakuruhusu kukagua uthibitisho huo mwenyewe — hakuna haja ya kuamini brosha.',
  'vault.how.step1.body': 'Picha za programu za kipekee — gharama, dondoo za kisheria, maelezo ya njia — zinahesabiwa hash na kufungwa kwenye Bitcoin kupitia OpenTimestamps. Satohash.io inatoa risiti za uthibitisho zinazosomeka na urefu wa block.',
  'vault.how.step1.title': 'Nini hufungwa muhuri',
  'vault.how.step2.body': 'Uthibitisho uliothibitishwa una URL halisi za Satohash na faili za .ots kwenye diski. Nanga za onyesho ni viwakilishi vya mbegu — muhimu kwa majaribio ya UI lakini si uthibitisho huru wa mnyororo. Vipande vya kuchuja vinakuwezesha kuona kila njia wazi.',
