  'vault.educationEyebrow': 'Tresor-Wissensecke',
  'vault.educationTitle': 'So funktionieren OpenTimestamps-Beweise',
  'vault.educationBody': 'Kurze Einführung zum Hashing von Programmdaten, Hochladen von .ots-Belegen und Bestätigen von Ankern auf Bitcoin — Video folgt in einem zukünftigen BUILD.',
  'vault.educationStub': 'Walkthrough ansehen (demnächst)',
  'vault.educationStubHint': 'Video-Platzhalter — Kamerawalkthrough-Stub',
  'vault.doc.title': 'Stemple deine eigenen Dokumente',
  'vault.doc.subtitle': 'Lege jede Datei ab (Pass-Scan, Vertrag, Bewerbung) — sie wird lokal gehasht und der SHA-256 wird über die Satohash-API auf Bitcoin verankert. Die Datei selbst verlässt dieses Gerät nie.',
  'vault.doc.pick': 'Zu stempelnde Dokumente wählen',
  'vault.doc.dropTitle': 'Datei hier ablegen (oder klicken, um zu durchsuchen)',
  'vault.doc.dropDescription': 'Hash bleibt lokal — nur der SHA-256 wird an Satohash gesendet',
  'vault.doc.stamping': 'Hashing und Stempeln',
  'vault.doc.refresh': 'Ankerstatus neu prüfen',
  'vault.doc.copyHash': 'Inhalts-Hash kopieren',
  'vault.doc.verify': 'Auf Satohash verifizieren',
  'vault.doc.delete': 'Aus dem Register entfernen',
  'vault.doc.status.pending': 'Ausstehend',
  'vault.doc.status.confirmed': 'Bestätigt',
  'vault.doc.status.error': 'Fehler',
  'vault.doc.confirmedBlock': 'Block {block}',
  'vault.doc.privacyNote': 'Dateien werden nie hochgeladen oder gespeichert — nur der Hash wird gestempelt. Ein bestätigter Stempel beweist, dass diese exakte Datei zu diesem Bitcoin-Block existierte. Dieses Register wird nur auf diesem Gerät gespeichert.',
  'vault.lineageTitle': 'Beweis-Abstammung',
  'vault.expandLineage': 'Abstammung',
  'vault.collapseLineage': 'Abstammung ausblenden',
  'vault.nostrPublish': 'Auf Nostr ankündigen',
  'vault.blockLabel': 'Block',
  'vault.hashLabel': 'Inhalts-Hash',
  'vault.otsLabel': 'OTS-Beleg',
  'vault.tip.badgeVerified': 'Bitcoin-verifiziert — Satohash bestätigt, dass dieser Anker in einem Bitcoin-Block liegt. Der stärkste Beweisstatus.',
  'vault.tip.badgeRecorded': 'Beweis in den Akten — Hash und Block sind hier festgehalten. Bestätige auf Satohash für den finalen on-chain-Anker.',
  'vault.tip.badgePending': 'Anker ausstehend — an den Zeitstempeldienst übermittelt, wartet auf einen Bitcoin-Block.',
  'vault.tip.badgeDemo': 'Demo-Anker — ein Platzhalter aus Seed-Daten. Noch nicht auf Bitcoin gestempelt.',
  'vault.tip.block': 'Der Bitcoin-Block, in dem dieser Beweis verankert ist — ein permanenter, öffentlicher Zeitstempel, den jeder prüfen kann.',
  'vault.tip.checked': 'Wann dieses Programm zuletzt überprüft wurde.',
  'vault.tip.hash': 'SHA-256-Fingerabdruck der verankerten Daten — er beweist, dass dieser exakte Inhalt zu diesem Block existierte.',
  'vault.tip.ots': 'OpenTimestamps-Beleg (.ots). Lade ihn herunter, um unabhängig zu prüfen — ohne Konto oder Dienst.',
  'vault.tip.useProof': 'Hänge diesen Beweis-Hash als Nachweis an eine Passbewerbung an.',
  'vault.tip.copyUrl': 'Kopiere den Satohash-Verifizierungslink zum Teilen oder Speichern.',
  'vault.tip.satohash': 'Öffne Satohash.io, um diesen Beweis auf Bitcoin zu prüfen.',
  'vault.tip.otsDownload': 'Lade den OpenTimestamps-Beleg für die Offline-Prüfung herunter.',
  'vault.tip.apply': 'Starte eine Bewerbung für dieses Programm mit vorab angehängtem Beweis.',
  'vault.tip.nostr': 'Veröffentliche eine signierte Zeitstempel-Ankündigung auf deinen Nostr-Relays. Nostr ist Klatsch — der OTS/Satohash-Beweis ist der Nachweis.',
  'vault.tip.lineage': 'Jeder für dieses Programm aufgezeichnete Beweis — sieh, wie sich der Anker im Laufe der Zeit entwickelt hat.',
  'vault.tip.lineageEventId': 'Kopiere die Nostr-Ereignis-ID — deine signierte Beweis-Ankündigung. Bewahre sie auf, um das Ereignis später zu referenzieren.',
  'vault.how.eyebrow': 'SO FUNKTIONIERT ES',
  'vault.how.title': 'Warum der Tresor existiert — und wie man ihn nutzt',
  'vault.how.intro': 'Der Tresor ist das Seal-Pillar von MotoPass. Jeder materielle Programm-Anspruch sollte eine Bitcoin-Geburtsurkunde tragen. Diese Seite lässt dich diese Beweise selbst prüfen — kein Prospekt-Vertrauen erforderlich.',
  'vault.how.step1.title': 'Was gestempelt wird',
  'vault.how.step1.body': 'Flaggschiff-Programm-Schnappschüsse — Kosten, Rechtstexte, Weg-Notizen — werden gehasht und per OpenTimestamps auf Bitcoin verankert. Satohash.io liefert menschenlesbare Verifizierungsbelege mit Blockhöhe.',
  'vault.how.step2.title': 'Verifizierte vs. Demo-Anker',
  'vault.how.step2.body': 'Verifizierte Beweise haben echte Satohash-URLs und optionale .ots-Dateien auf der Festplatte. Demo-Anker sind Seed-Platzhalter — nützlich für UI-Tests, aber kein unabhängiger Chain-Beweis. Filterchips zeigen dir jede Bahn klar.',
  'vault.how.step3.title': 'In deinem Browser prüfen',
  'vault.how.step3.body': 'Füge einen SHA-256-Inhalts-Hash ein, lade eine passende .ots-Datei hoch oder klicke auf „Diesen Beweis verwenden“ auf einer Programm-Karte. MotoPass validiert das Format lokal und verlinkt dich für die unabhängige Prüfung zu Satohash.',
  'vault.how.step4.title': 'Beweis-Abstammung teilen',
  'vault.how.step4.body': 'Kopiere einen Nostr kind:30078-Ereignis-Stub, um Programm-Updates auf deinem Relay zu senden. Kombiniere ihn mit Bewerben, um deinen eigenen Bewerbungshash zu stempeln — dieselbe Pipeline, die Betreiber für die Sorgfaltspflicht nutzen.',
  'vault.how.footer': 'Nur zu Bildungszwecken — keine Rechts-, Steuer- oder Anlageberatung. MotoPass verwahrt keine Dokumente; du prüfst unabhängig auf Bitcoin.',
  'distressed.how.eyebrow': 'SO FUNKTIONIERT ES',
  'distressed.how.title': 'Warum Distressed existiert — und wie Deals fließen',
  'distressed.how.intro': 'Distressed ist das Forge-Pillar von MotoPass — ein beweisgeschützter Marktplatz für souveräne Plays, die unterbewertet, kapital-effizient oder strukturell interessant sind. Keine Listings-Seite. Jede Zeile erfordert einen Satohash-Beweis, bevor sie erscheint.',
  'distressed.how.step1.title': 'Wie Listings aufgebaut werden',
  'distressed.how.step1.body': 'Nur Programme mit Flaggschiff-Tiefe, Wegen und Satohash-Beweisen qualifizieren sich. Jedes Listing zeigt einen Weg, ein ₿-erstes Gebot, rote Flaggen und Optimierungstipps aus Live-countries.json — kein statischer Marketingtext.',
  'distressed.how.step2.title': 'Kuratiert vs. erlaubnisfrei',
  'distressed.how.step2.body': 'Kuratierte Bahn: Top-Score-Plays, von Kimi für die Betreiber-Passung ausgewählt. Erlaubnisfreie Bahn: gleiche Beweis-Pforte, aber Vorsicht beim Käufer — MotoPass koordiniert Intelligenz, keine Verwahrung. Beide Bahnen erfordern proof_url.',
  'distressed.how.step3.title': 'Den Distressed-Score lesen',
  'distressed.how.step3.body': 'Der Score 1–5 bewertet Kapital-Effizienz und Wertsignale — niedrigere Minimums, Solvenzrouten, Budget-Keywords und Souveränitäts-Kompromisse. Filtere nach Region, Min-Score und Max-Gebot, um deine Stack-Kandidaten einzugrenzen.',
  'distressed.how.step4.title': 'Vom Listing zum Deal-Room',
  'distressed.how.step4.body': 'Öffne eine Karte → prüfe den Beweis im Tresor → prüfe die Escrow-Vorlage (PSBT-Stub, keine Fondssverwahrung) → bewirb dich oder eskaliere an einen Kimi-Agenten im Deal-Room. MotoPass hält dein Bitcoin nie.',
  'distressed.how.footer': 'Nur Vorlagen-Escrow. Bildungs-Intelligenz — keine Rechts-, Steuer- oder Anlageberatung. Führe vor Kapitalbindung eine unabhängige Sorgfaltspflicht durch.',
  'distressed.filtersTitle': 'Listing-Verzeichnis',
