  'pitch.faq.eyebrow': 'FAQ',
  'pitch.faq.title': 'Fragen, die Betreiber zuerst stellen',
  'pitch.ctaBand.title': 'Bereit, mit Beweis zu stapeln?',
  'pitch.ctaBand.sub': 'Entdecke Jurisdiktionen, prüfe Anker und registriere Interesse — souveräne Mobilität ohne Prospekt-Vertrauen.',
  'pitch.ctaBand.apply': 'Bewerbungen öffnen',
  'pitch.ctaBand.explore': 'Programme durchsuchen',
  'pitch.ctaBand.vault': 'Tresor erkunden',
  'pitch.faq.q1': 'Was ist MotoPass?',
  'pitch.faq.a1': 'MotoPass ist eine Bitcoin-native Plattform zur Bewertung, zum Vergleich und zum Stacken souveräner Aufenthalts- und Staatsbürgerschaftsprogramme mit Satohash-verifizierten Daten und Nostr-Identität.',
  'pitch.faq.q2': 'Wie funktioniert die Satohash-Verifizierung?',
  'pitch.faq.a2': 'Materielle Behauptungen werden gehasht und per OpenTimestamps an Bitcoin verankert. Jeder kann die Beweise unabhängig auf Satohash.io prüfen, ohne einem Prospekt-Schnappschuss zu vertrauen.',
  'pitch.faq.q3': 'Brauche ich eine E-Mail, um mich zu bewerben?',
  'pitch.faq.a3': 'Nein. MotoPass nutzt die Nostr-npub-native Registrierung — verbinde deine Browsererweiterung und dein öffentlicher Schlüssel wird dein Konto.',
  'pitch.faq.q4': 'Wofür ist der Tresor?',
  'pitch.faq.a4': 'Der Tresor ist der Ort, an dem du Satohash-Beweise prüfst — füge einen Inhalts-Hash ein, lade eine OpenTimestamps-Datei hoch oder wähle ein Programm und prüfe Anker auf Bitcoin, ohne MotoPass beim Wort zu nehmen.',
  'pitch.faq.q5': 'Was ist Distressed?',
  'pitch.faq.a5': 'Distressed ist ein beweisgeschützter Marktplatz für kapital-effiziente souveräne Plays. Listings erfordern einen Satohash-Beweis, zeigen ₿-Gebote zuerst und bieten Vorlagen-Escrow plus Kimi-Agenten-Eskalation — MotoPass verwahrt niemals Gelder.',
  'pitch.guide.eyebrow': 'MOTOPASS VERSTEHEN',
  'pitch.guide.title': 'Eine Plattform, vier Pillars, null Prospekt-Vertrauen',
  'pitch.guide.intro': 'MotoPass ist das private Betriebssystem für souveräne Betreiber — Jurisdiktionen recherchieren, Behauptungen auf Bitcoin prüfen, deinen Stack verfolgen und über Nostr koordinieren. Hier ist die komplette Reise von links nach rechts.',
  'pitch.guide.step1.title': 'Forge — entdecken & modellieren',
  'pitch.guide.step1.body': 'Starte in Programmen: filtere 50 Jurisdiktionen, starte den Stack-Simulator, vergleiche Gebühren und prüfe die BTC-Karten-Händlerdichte. Distressed bringt beweisgeschützte Wertspiele hervor, wenn du kapital-effiziente Routen willst.',
  'pitch.guide.step2.title': 'Seal — auf Bitcoin verifizieren',
  'pitch.guide.step2.body': 'Jeder materielle Anspruch sollte sich in einem Bitcoin-Block verankern. Der Tresor lässt dich Hashes einfügen, .ots-Dateien hochladen und Beweise unabhängig über Satohash.io prüfen — Wahrheit, die du prüfen kannst.',
  'pitch.guide.step3.title': 'Ledger — deinen Stack verfolgen',
  'pitch.guide.step3.body': 'Speichere erworbene Programme im Portfolio, modelliere Multi-Jurisdiktions-Stacks und überwache Souveränitäts-Scores, Lightning-Bereitschaft und Verlängerungszeitrahmen aus Live-Programmdaten.',
  'pitch.guide.step4.title': 'Nexus — bewerben & koordinieren',
  'pitch.guide.step4.body': 'Verbinde deinen npub, registriere Interesse bei Bewerben (launch-gated), stemple deinen Bewerbungshash und eskaliere an Kimi-Verbindungsagenten — keine E-Mail, kein Salesforce, kein Samtseil.',
  'pitch.guide.footer': 'Nur Bildungs-Intelligenz — keine Rechts-, Steuer-, Einwanderungs- oder Anlageberatung. Prüfe jede Behauptung unabhängig, bevor du Kapital bindest.',
  'pitch.guide.cta': 'Öffnen',
