  'distressed.how.eyebrow': '仕組み',
  'distressed.how.footer': 'テンプレートエスクローのみ。教育目的の情報 — 法務・税務・投資の助言ではありません。資金を投じる前に独立したデューデリジェンスを実施してください。',
  'distressed.how.intro': 'DistressedはMotoPassのForgeピラー — 過小評価・資本効率重視・構造的に興味深い主権的プレイのための証明ゲート付きマーケットプレイスです。掲載サイトではありません。掲載されるすべての行にSatohash証明が必要です。',
  'distressed.how.step1.body': '経路とSatohash証明を持つフラッグシップ深度プログラムのみが対象です。各掲載は1つの経路、₿優先のアスク、レッドフラグ、ライブcountries.jsonから取得した最適化のヒントを表示します — 静的なマーケティングコピーではありません。',
  'distressed.how.step1.title': '掲載の仕組み',
  'distressed.how.step2.body': 'キュレーション・レーン: オペレーター適合性でKimiが厳選した高スコアプレイ。パーミッションレス・レーン: 同じ証明ゲートですが、買い手責任 — MotoPassは情報を調整し、保管はしません。どちらのレーンもproof_urlが必要です。',
  'distressed.how.step2.title': 'キュレーション vs パーミッションレス',
  'distressed.how.step3.body': 'スコア1–5は資本効率と価値シグナルをランク付け — 低い最低額、ソルベンシールート、予算キーワード、主権性トレードオフ。地域・最低スコア・最大アスクで絞り込んでスタック候補を絞り込みます。',
  'distressed.how.step3.title': 'ディストレススコアの読み方',
