  'pitch.ctaBand.sub': '法域を探索し、アンカーを検証し、関心を登録 — パンフレット信頼なしの主権的モビリティ。',
  'pitch.ctaBand.title': '証明付きでスタックする準備はできましたか？',
  'pitch.ctaBand.vault': 'Vaultを探索',
  'pitch.faq.a1': 'MotoPassは、Satohash検証済みデータとNostrアイデンティティで、主権的な永住権・市民権プログラムを評価・比較・スタッキングするためのBitcoinネイティブなプラットフォームです。',
  'pitch.faq.a2': '重要な主張はハッシュ化され、OpenTimestamps経由でBitcoinにアンカーされます。誰でもパンフレットのスナップショットを信じることなく、Satohash.ioで証明を独立検証できます。',
  'pitch.faq.a3': 'いいえ。MotoPassはNostrのnpubネイティブ登録を使用します — ブラウザ拡張機能を接続すると、公開鍵があなたのアカウントになります。',
  'pitch.faq.a4': 'VaultはSatohash証明を監査する場所です — コンテンツハッシュを貼り付け、OpenTimestampsファイルをアップロード、またはプログラムを選んで、MotoPassの言葉を信じずにBitcoin上のアンカーを検証します。',
  'pitch.faq.a5': 'Distressedは資本効率重視の主権的プレイのための証明ゲート付きマーケットプレイスです。掲載にはSatohash証明が必要で、₿アスクを先に表示し、テンプレートエスクローとKimiエージェントへのエスカレーションを提供します — MotoPassは資金を保管しません。',
  'pitch.faq.eyebrow': 'よくある質問',
