  'vault.tip.lineageEventId': 'Nostr इवेंट id कॉपी करें — आपकी हस्ताक्षरित प्रमाण घोषणा। बाद में संदर्भ के लिए इसे रखें।',
  'vault.searchPrograms': 'कार्यक्रम द्वारा प्रमाण खोजें…',
  'vault.archiveBanner': '{count} स्टैम्प्ड कार्यक्रम प्रमाण · स्वतंत्र OTS सत्यापन',
  'vault.exportSelected': '{count} चयनित निर्यात करें',
