  'vault.selectProof': '{name} चुनें',
  'vault.demoWatermark': 'डेमो',
  'vault.copyEventId': 'इवेंट id कॉपी करें',
  'vault.how.eyebrow': 'यह कैसे काम करता है',
  'vault.how.title': 'तिजोरी क्यों है — और इसका उपयोग कैसे करें',
  'vault.how.intro': 'तिजोरी MotoPass का Seal स्तंभ है। हर भौतिक कार्यक्रम दावे पर बिटकॉइन जन्म प्रमाणपत्र होना चाहिए। यह पृष्ठ आपको उन प्रमाणों की स्वयं ऑडिट करने देता है — कोई ब्रोशर भरोसा आवश्यक नहीं।',
  'vault.how.step1.title': 'क्या स्टैम्प होता है',
  'vault.how.step1.body': 'फ्लैगशिप कार्यक्रम स्नैपशॉट — लागत, कानूनी अंश, रास्ते के नोट — OpenTimestamps के ज़रिए हैश और बिटकॉइन पर एंकर्ड होते हैं। Satohash.io ब्लॉक ऊँचाई के साथ मानव-पठनीय सत्यापन रसीदें देता है।',
  'vault.how.step2.title': 'सत्यापित बनाम डेमो एंकर',
  'vault.how.step2.body': 'सत्यापित प्रमाणों के पास वास्तविक Satohash URL और वैकल्पिक .ots फ़ाइलें डिस्क पर होती हैं। डेमो एंकर सीड प्लेसहोल्डर हैं — UI परीक्षण के लिए उपयोगी पर स्वतंत्र चेन प्रमाण नहीं। फ़िल्टर चिप्स आपको हर लेन स्पष्ट देखने देते हैं।',
  'vault.how.step3.title': 'अपने ब्राउज़र में सत्यापित करें',
  'vault.how.step3.body': 'SHA-256 सामग्री हैश पेस्ट करें, मेल खाती .ots फ़ाइल अपलोड करें, या किसी कार्यक्रम कार्ड पर «इस प्रमाण का उपयोग करें» क्लिक करें। MotoPass प्रारूप स्थानीय रूप से सत्यापित करता है और स्वतंत्र सत्यापन के लिए आपको Satohash से जोड़ता है।',
  'vault.how.step4.title': 'प्रमाण वंशावली साझा करें',
  'vault.how.step4.body': 'अपने रिले पर कार्यक्रम अद्यतन प्रसारित करने के लिए Nostr kind:30078 इवेंट स्टब कॉपी करें। अपना आवेदन हैश स्टैम्प करने के लिए Apply के साथ जोड़ें — वही पाइपलाइन जो ऑपरेटर परिश्रम के लिए उपयोग करते हैं।',
  'vault.how.footer': 'केवल शैक्षिक — कानूनी, कर या निवेश सलाह नहीं। MotoPass दस्तावेज़ रखता नहीं; आप बिटकॉइन पर स्वयं सत्यापित करते हैं।',
  'distressed.how.eyebrow': 'यह कैसे काम करता है',
  'distressed.how.title': 'संकटग्रस्त क्यों है — और सौदे कैसे चलते हैं',
  'distressed.how.intro': 'संकटग्रस्त MotoPass का Forge स्तंभ है — अवमूल्यित, पूंजी-कुशल या संरचनात्मक रूप से दिलचस्प संप्रभु सौदों के लिए प्रमाण-संरक्षित बाज़ार। लिस्टिंग साइट नहीं। हर पंक्ति दिखने से पहले Satohash प्रमाण माँगती है।',
  'distressed.how.step1.title': 'लिस्टिंग कैसे बनती हैं',
  'distressed.how.step1.body': 'केवल रास्तों और Satohash प्रमाणों वाले फ्लैगशिप-गहराई कार्यक्रम योग्य होते हैं। हर लिस्टिंग एक रास्ता, ₿-पहले माँग, लाल झंडे और लाइव countries.json से खींचे अनुकूलन सुझाव दिखाती है — स्थिर मार्केटिंग कॉपी नहीं।',
  'distressed.how.step2.title': 'चयनित बनाम अनुमति-मुक्त',
  'distressed.how.step2.body': 'चयनित लेन: ऑपरेटर अनुकूलता के लिए Kimi द्वारा चुने गए शीर्ष-स्कोरिंग सौदे। अनुमति-मुक्त लेन: वही प्रमाण द्वार, पर खरीदार सावधान — MotoPass बुद्धिमत्ता का समन्वय करता है, हिरासत नहीं। दोनों लेन proof_url माँगती हैं।',
  'distressed.how.step3.title': 'संकटग्रस्त स्कोर पढ़ना',
  'distressed.how.step3.body': 'स्कोर 1–5 पूंजी दक्षता और मूल्य संकेतों को रैंक करता है — कम न्यूनतम, समाधान मार्ग, बजट कीवर्ड और संप्रभुता व्यापार-बंद। अपने स्टैक उम्मीदवारों को सीमित करने के लिए क्षेत्र, न्यूनतम स्कोर और अधिकतम माँग से फ़िल्टर करें।',
  'distressed.how.step4.title': 'लिस्टिंग से डील रूम तक',
  'distressed.how.step4.body': 'एक कार्ड खोलें → तिजोरी में प्रमाण सत्यापित करें → एस्क्रो टेम्पलेट की समीक्षा करें (PSBT स्टब, कोई फंड हिरासत नहीं) → आवेदन करें या डील रूम में Kimi एजेंट तक बढ़ाएँ। MotoPass आपका बिटकॉइन कभी नहीं रखता।',
  'distressed.how.footer': 'केवल टेम्पलेट एस्क्रो। शैक्षिक बुद्धिमत्ता — कानूनी, कर या निवेश सलाह नहीं। पूंजी लगाने से पहले स्वतंत्र परिश्रम करें।',
