  'agents.how.eyebrow': 'यह कैसे काम करता है',
  'agents.how.title': 'एजेंट क्यों हैं — और Nexus आपके स्टैक का समन्वय कैसे करता है',
  'agents.how.intro': 'एजेंट MotoPass का Nexus स्तंभ है — क्लब परत जहाँ संप्रभु ऑपरेटर Nostr के ज़रिए जुड़ते हैं, देश-विशिष्ट मार्गदर्शन पाते हैं, और ईमेल या ब्रोशर गेटकीपर के बिना शोध से स्टैम्प्ड आवेदन तक बढ़ते हैं।',
  'agents.how.step1.title': 'अपना npub कनेक्ट करें',
  'agents.how.step1.body': 'MotoPass Nostr-मूल है। अपना ब्राउज़र एक्सटेंशन (Alby, nos2x, आदि) कनेक्ट करें और आपकी सार्वजनिक कुंजी Apply, Agents और भविष्य के क्लब रिले में आपकी पहचान बन जाती है — कोई ईमेल साइनअप नहीं।',
  'agents.how.step2.title': 'Kimi समन्वय करता है, देश एजेंट सलाह देते हैं',
  'agents.how.step2.body': 'Kimi M4 HERMES पर आपका रणनीतिक संपर्क है — वह आपको क्षेत्राधिकार-विशिष्ट एजेंटों (उरुग्वे, अल साल्वाडोर, यूएई, और अधिक) तक रूट करती है जो फ्लैगशिप कार्यक्रम डेटा और Satohash प्रमाण आवश्यकताओं पर प्रशिक्षित हैं।',
  'agents.how.step3.title': 'प्रमाण संदर्भ के साथ संदेश',
  'agents.how.step3.body': 'हर एजेंट कार्ड कार्यक्रम संदर्भ से पहले से भरा एक Nostr DM स्टब (kind:14) खोलता है। तिजोरी सत्यापन और संकटग्रस्त लिस्टिंग के साथ जोड़ें ताकि हर बातचीत स्वतंत्र रूप से सत्यापन योग्य दावों का संदर्भ दे।',
  'agents.how.step4.title': 'रुचि से आवेदन तक बढ़ें',
  'agents.how.step4.body': 'Apply पर रुचि दर्ज करें (लॉन्च-गेटेड), अपना आवेदन हैश बिटकॉइन पर स्टैम्प करें, फिर दस्तावेज़ तैयारी, रास्ता अनुकूलन और सलाह हस्तांतरण के समन्वय के लिए Nostr के ज़रिए यहाँ लौटें।',
  'agents.how.footer': 'एजेंट मार्गदर्शन शैक्षिक बुद्धिमत्ता है — कानूनी, कर, आव्रजन या निवेश सलाह नहीं। पूंजी लगाने से पहले हर दावे को बिटकॉइन पर सत्यापित करें।',
  'agents.nexus.title': 'एलिट संप्रभु Nexus',
  'agents.nexus.sub': 'Nostr पहचान · Kimi समन्वय · BTC/Lightning रेल · बिना वेलवेट रस्सी के क्लब समन्वय',
  'agents.paige.title': 'Paige AI कॉन्सियर्ज',
  'agents.paige.body': 'countries.json में आधारित क्षेत्राधिकार प्रश्न पूछें। Paige उपलब्ध होने पर Satohash प्रमाण ID का हवाला देती है और असत्यापित क्षेत्रों को ईमानदारी से चिह्नित करती है। मानव निर्णय की आवश्यकता होने पर Kimi या देश एजेंटों तक बढ़ाती है।',
  'agents.dealroom.title': 'डील रूम वृद्धि',
